//! Telemetry-only scheduling lives in the destination's existing progress ledger.
//! Bodies are regenerated by the ordinary evidence chunk, never kept in an outbox.
use super::*;
use crate::claude_local_otel::{self as otel, TelemetryGeneration};
use time::{format_description::well_known::Rfc3339, OffsetDateTime};

pub(super) const CONTRACT: &str = "claude_otel_only_sessions:v1";
#[derive(Clone, Copy)]
pub(super) struct Window {
    floor: i128,
    ceiling: Option<i128>,
    start: i128,
}
fn clock(value: &str) -> Option<i128> {
    OffsetDateTime::parse(value, &Rfc3339)
        .ok()
        .map(|t| t.unix_timestamp_nanos())
}
const SLACK: i128 = 300_000_000_000;
pub(super) fn advertised(hint: &crate::snapshot_client::ActivityHintResponse) -> Option<Window> {
    if hint.source != "claude_code"
        || !hint.local_usage_reconciliation_enabled
        || !hint.snapshot_head_cas_enabled
        || hint.claude_otel_only_sessions_contract.as_deref() != Some(CONTRACT)
    {
        return None;
    }
    let floor = clock(hint.claude_otel_only_pairing_floor.as_deref()?)?;
    let ceiling = match hint.claude_otel_only_pairing_ceiling.as_deref() {
        Some(value) => Some(clock(value)?),
        None => None,
    };
    if ceiling.is_some_and(|end| end <= floor + 2 * SLACK) {
        return None;
    }
    Some(Window {
        floor,
        ceiling,
        start: floor + SLACK,
    })
}
#[derive(Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub(super) struct Ledger {
    floor: i128,
    start: i128,
    #[serde(default)]
    candidates: BTreeMap<String, Candidate>,
}
#[derive(Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
struct Candidate {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    built: Option<Built>,
    #[serde(skip)]
    reading: Option<TelemetryGeneration>,
}
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
struct Built {
    fingerprint: String,
    body: String,
    generation: TelemetryGeneration,
}
impl std::fmt::Debug for Ledger {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("TelemetryCandidates")
            .field("count", &self.candidates.len())
            .finish()
    }
}
crate::heap_layout_bound::fields!(Ledger; floor, start, candidates);
crate::heap_layout_bound::fields!(Candidate; built, reading);
crate::heap_layout_bound::fields!(Built; fingerprint, body, generation);

impl Ledger {
    pub(super) fn settle(&mut self, root: &str) {
        self.candidates.remove(root);
    }
    pub(super) fn references(&self) -> impl Iterator<Item = &str> {
        self.candidates
            .values()
            .filter_map(|c| c.built.as_ref())
            .map(|b| b.fingerprint.as_str())
    }
}

/// Whether a seeded candidate's current generation needs a body.
fn owed(
    candidate: &Candidate,
    generation: &TelemetryGeneration,
    accepted: &BTreeMap<String, String>,
    contexts: &BTreeMap<String, String>,
    resend: &super::upload_context_resend::Cycle,
) -> bool {
    generation.api.is_some()
        && generation.trace.is_some()
        && candidate.built.as_ref().is_none_or(|built| {
            otel::telemetry_not_truncated(generation, &built.generation)
                && !(built.generation == *generation
                    && accepted.get(&built.fingerprint) == Some(&built.body)
                    && !resend.requires_resend(&built.fingerprint, contexts))
        })
}

impl SnapshotUploadProgress {
    /// Telemetry-only work only a walking pass takes up (`walk_idle`).
    pub(super) fn telemetry_owes_walk(
        &self,
        support: &Path,
        hint: &crate::snapshot_client::ActivityHintResponse,
        index: &ScanIndex,
    ) -> bool {
        let Some(window) = advertised(hint) else {
            return false;
        };
        let Some(ledger) = (self.telemetry_only.as_ref()).filter(|l| l.floor == window.floor)
        else {
            return true;
        };
        if !otel::telemetry_notices::pending(support).is_ok_and(|pending| pending.is_empty()) {
            return true;
        }
        let candidates = ledger.candidates.keys().cloned().collect();
        let (absent, _) =
            crate::snapshots::claude_request_money::e2::telemetry_scope(index, &candidates);
        ledger.candidates.iter().any(|(root, candidate)| {
            absent.contains(root)
                && otel::telemetry_generation(support, root).is_ok_and(|generation| {
                    owed(
                        candidate,
                        &generation,
                        &self.accepted_body_witnesses,
                        &self.accepted_body_contexts,
                        &self.context_resend,
                    )
                })
        })
    }

    /// Shared across the whole ACK-retirement owner, including capacity and recovery.
    pub(super) fn ack_incidence<'a>(
        &'a self,
        index: &'a ScanIndex,
    ) -> impl Iterator<Item = &'a str> {
        index.upload_progress_ack_incidence().chain(
            self.telemetry_only
                .iter()
                .flat_map(|ledger| ledger.references()),
        )
    }

    pub(super) fn seed_telemetry(
        &mut self,
        support: &Path,
        hint: &crate::snapshot_client::ActivityHintResponse,
        scan: &mut SourceScanResult,
        index: &ScanIndex,
        progress_path: &Path,
    ) -> Result<Option<Window>> {
        let Some(mut window) = advertised(hint) else {
            otel::telemetry_notices::configure(support, false)?;
            return Ok(None);
        };
        let fresh = self
            .telemetry_only
            .as_ref()
            .is_none_or(|ledger| ledger.floor != window.floor);
        if fresh {
            let ledger = self.telemetry_only.get_or_insert_with(Default::default);
            ledger.floor = window.floor;
            ledger.start = OffsetDateTime::now_utc()
                .unix_timestamp_nanos()
                .max(window.start);
            self.save(progress_path)?;
        }
        otel::telemetry_notices::configure(support, true)?;
        let pending = otel::telemetry_notices::pending(support)?;
        if !pending.is_empty() {
            let ledger = self.telemetry_only.as_mut().expect("activated ledger");
            for root in &pending {
                ledger.candidates.entry(root.clone()).or_default();
            }
            self.save(progress_path)?;
        }
        otel::telemetry_notices::forget(support, &pending)?;
        // Page facts are captured before any synthetic slot exists. An all-copy
        // page still has a transcript, even when later normalization emits none.
        let page_roots = claude_evidence_session_ids(&scan.snapshots)
            .into_iter()
            .collect::<BTreeSet<_>>();
        let accepted = &self.accepted_body_witnesses;
        let contexts = &self.accepted_body_contexts;
        let resend = &self.context_resend;
        let ledger = self.telemetry_only.as_mut().expect("activated ledger");
        window.start = ledger.start;
        let candidates = ledger.candidates.keys().cloned().collect();
        let (absent, backed) =
            crate::snapshots::claude_request_money::e2::telemetry_scope(index, &candidates);
        ledger
            .candidates
            .retain(|root, _| !page_roots.contains(root) && !backed.contains(root));
        for (root, candidate) in &mut ledger.candidates {
            if !absent.contains(root) {
                continue;
            }
            let Ok(generation) = otel::telemetry_generation(support, root) else {
                continue;
            };
            if !owed(candidate, &generation, accepted, contexts, resend) {
                continue;
            }
            candidate.reading = Some(generation);
            scan.snapshots.push(SnapshotItem::neutral_telemetry(
                root.clone(),
                current_rfc3339(),
            ));
        }
        Ok(Some(window))
    }

    /// Called after ordinary policy/finalization, before upload. The generations
    /// captured before strict decode must still match; no ACK-time stat mints proof.
    pub(super) fn bind_telemetry_bodies(&mut self, support: &Path, items: &mut Vec<SnapshotItem>) {
        let Some(ledger) = self.telemetry_only.as_mut() else {
            return;
        };
        items.retain(|item| {
            if item.evidence_basis != Some("otel_only") {
                return true;
            }
            let Some(candidate) = ledger.candidates.get_mut(&item.source_session_id) else {
                return false;
            };
            let Some(generation) = candidate.reading.take() else {
                return false;
            };
            if otel::telemetry_generation(support, &item.source_session_id)
                .ok()
                .as_ref()
                != Some(&generation)
            {
                return false;
            }
            candidate.built = Some(Built {
                fingerprint: item.snapshot_fingerprint.clone(),
                body: snapshot_upload_body_witness(item),
                generation,
            });
            true
        });
    }

    pub(super) fn settle_telemetry_root(&mut self, root: &str) {
        if let Some(ledger) = self.telemetry_only.as_mut() {
            ledger.candidates.remove(root);
        }
    }
}

/// Called inside the ordinary evidence chunk with its already-strict loaded rows.
pub(super) fn build(
    mut item: SnapshotItem,
    api: &otel::ClaudeLocalOtelLoadReport,
    trace: &otel::ClaudeTraceOwnershipLoadReport,
    index: &ScanIndex,
    window: Window,
    accepted: Option<&crate::snapshots::claude_request_identity::AcceptedBuckets>,
    budget: crate::snapshots::claude_request_identity::WireBudget<'_>,
) -> Result<Option<SnapshotItem>, ()> {
    use crate::snapshots::{
        claude_request_census, claude_request_identity, claude_request_money::e2,
    };
    let root = item.source_session_id.as_str();
    // The caller already proved a healthy strict read, including empty files.
    let rows = api.evidence.get(root).map(Vec::as_slice).unwrap_or(&[]);
    let mut unique = BTreeMap::new();
    for row in rows {
        if unique
            .insert(row.request_id.as_str(), row)
            .is_some_and(|old: &otel::ClaudeLocalOtelEvidence| old.fingerprint != row.fingerprint)
        {
            return Err(());
        }
    }
    let traces = trace.evidence.get(root).map(Vec::as_slice).unwrap_or(&[]);
    let trace_ids = traces
        .iter()
        .map(|row| row.request_id.as_str())
        .collect::<BTreeSet<_>>();
    if trace_ids != unique.keys().copied().collect() {
        return Err(());
    }
    if unique.is_empty() {
        return Ok(None);
    }
    if traces
        .iter()
        .any(|row| !crate::snapshots::claude_trace_evidence_fingerprint_is_valid(row))
    {
        return Err(());
    }
    let wanted = unique
        .keys()
        .map(|id| claude_request_census::claude_request_hash(id))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let held = claude_request_census::positive_holders(index, &wanted);
    let mut entity = e2::ClaudeEntityBody::default();
    let mut first = i128::MAX;
    let mut last = i128::MIN;
    for row in unique.values() {
        let at = clock(&row.observed_at).ok_or(())?;
        // Never turn an old root's post-activation suffix into a fresh session.
        if at <= window.start || window.ceiling.is_some_and(|end| at >= end - SLACK) {
            return Ok(None); // Permanently before this pairing's admission window.
        }
        if held.contains(&claude_request_census::claude_request_hash(&row.request_id)) {
            continue;
        }
        if row.request_count != 1
            || row.session_id.as_ref() != root
            || !crate::snapshots::claude_api_evidence_fingerprint_is_valid(row)
        {
            return Err(());
        }
        e2::add_reported_row(
            &mut entity,
            row,
            claude_request_identity::side_call_account(row, root),
            None,
        )
        .ok_or(())?;
        first = first.min(at);
        last = last.max(at);
    }
    if entity.grains.is_empty() {
        return Ok(None);
    }
    entity.telemetry_owned_complete = true;
    let format = |at| {
        OffsetDateTime::from_unix_timestamp_nanos(at)
            .ok()?
            .format(&Rfc3339)
            .ok()
    };
    item.source_started_at = format(first);
    item.source_last_activity_at = format(last);
    if !e2::emit_entity(&mut item, &entity)
        || !claude_request_identity::tag_telemetry_entity(&mut item, &entity, accepted, budget)
    {
        return Err(());
    }
    Ok(Some(item))
}

#[cfg(test)]
mod tests;

impl std::error::Error for LocalHealthRefreshHeld {}

/// No local-health pass: no app is enabled, so this Mac has no source to
/// mint a relay token for. The heartbeat thread then runs the idle device
/// credential check instead (`control::probe_idle_device_credential`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct NoHeartbeatSource;

impl std::fmt::Display for NoHeartbeatSource {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("registered device has no enabled sources")
    }
}

impl std::error::Error for NoHeartbeatSource {}

/// What one off-pass local-health pass did, for the idle credential check.
pub(crate) enum LocalHealthPass {
    /// Stopped before looking for a heartbeat source: no readable credential,
    /// a credential change in progress, or no machine identity.
    PreSource(anyhow::Error),
    /// No heartbeat source: no app is enabled.
    NoSource,
    /// A heartbeat source was found and the upload ran, with this result.
    SourceRan(Result<()>),
}

pub fn upload_local_health_projection_now(daemon: &LocalDaemon) -> Result<()> {
    match local_health_pass(daemon) {
        LocalHealthPass::PreSource(error) => Err(error),
        LocalHealthPass::NoSource => Err(anyhow::Error::new(NoHeartbeatSource)),
        LocalHealthPass::SourceRan(result) => result,
    }
}

pub(crate) fn local_health_pass(daemon: &LocalDaemon) -> LocalHealthPass {
    let _stage = StageWindow::begin("unknown", "offpass_local_health");
    let authority = match crate::control::capture_credential_authority() {
        Ok(authority) => authority,
        Err(error) => return LocalHealthPass::PreSource(error),
    };
    let machine_id = match snapshot_machine_id(&authority.device) {
        Ok(Some(machine_id)) => machine_id,
        Ok(None) => return LocalHealthPass::PreSource(anyhow!("machine identity is missing")),
        Err(error) => return LocalHealthPass::PreSource(error),
    };
    let Some(source) = heartbeat_source(&authority.device) else {
        return LocalHealthPass::NoSource;
    };
    let client = match snapshot_api_base_url() {
        Ok(base) => SnapshotApiClient::new(base),
        Err(error) => return LocalHealthPass::PreSource(error),
    };
    LocalHealthPass::SourceRan(upload_local_health_projection_reporting(
        &client,
        &authority,
        source,
        &machine_id,
        daemon,
    ))
}

/// How one settled upload attempt changes the refresh hold of the binding the
/// pass used.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RefreshHoldChange {
    Keep,
    ClearIfHeld,
    NoteFailure { terminal: bool },
}

/// Settle one upload attempt with the daemon: the head, the device fact, the
/// account-gone mark and the hold change all apply together, or none does.
fn settle_local_health_upload_attempt(
    daemon: &LocalDaemon,
    start: &crate::CredentialObservationStart,
    outcome: Result<(), LocalHealthUploadFailureKind>,
    account_gone: bool,
    binding: &[u8; 32],
    hold: RefreshHoldChange,
) {
    daemon.settle_local_health_upload(start, outcome, account_gone, || match hold {
        RefreshHoldChange::Keep => {}
        RefreshHoldChange::ClearIfHeld => clear_setup_run_refresh_hold_for(binding),
        RefreshHoldChange::NoteFailure { terminal } => {
            note_setup_run_refresh_failed(binding, terminal)
        }
    });
}

/// One local-health upload with exactly the captured credential. Every
/// attempt settles once against what it captured: a sign-in, promotion,
/// reset or setup-run change that happened while it was in flight drops its
/// result, including any hold or account change.
pub(super) fn upload_local_health_projection_reporting(
    client: &SnapshotApiClient,
    authority: &crate::control::CredentialAuthority,
    source: SnapshotSource,
    machine_id: &str,
    daemon: &LocalDaemon,
) -> Result<()> {
    let device = &authority.device;
    let device_secret = authority.secret.as_str();
    // The binding this pass's requests are for, from the captured credential
    // and setup run. Holds are set and cleared only for it.
    let binding = setup_run_refresh_binding(authority, source)?;
    let relay_binding = client.relay_auth_binding(device, device_secret, source);
    if let Some(held) = setup_run_refresh_hold_for(&binding) {
        // No request at all while held: the last `AuthRejected` upload event
        // stays the latest one, so local health keeps reporting the rejection.
        return Err(anyhow::Error::new(held));
    }
    let start = daemon
        .start_credential_observation(authority.epoch, authority.connection.clone())
        .map_err(|error| anyhow!("read local health state failed: {error}"))?;
    match upload_local_health_projection_with(
        client,
        device,
        device_secret,
        source,
        machine_id,
        daemon,
    ) {
        Ok(()) => {
            settle_local_health_upload_attempt(
                daemon,
                &start,
                Ok(()),
                false,
                &binding,
                RefreshHoldChange::ClearIfHeld,
            );
            Ok(())
        }
        Err(error)
            if local_health_upload_should_refresh_setup_run(&error)
                && crate::relay_auth::take_setup_refresh(relay_binding) =>
        {
            if let Err(refresh_error) =
                crate::control::refresh_setup_run_token_for_persisted_connection()
            {
                // Terminal refresh failure indicating the bound account was
                // deleted server-side: transition the binding to the
                // unbound-equivalent `account_not_found` state so the next
                // sign-in (by any user) is a fresh first claim instead of a
                // reset-required dead end.
                settle_local_health_upload_attempt(
                    daemon,
                    &start,
                    Err(LocalHealthUploadFailureKind::AuthRejected),
                    crate::control::backend_error_indicates_account_gone(&refresh_error),
                    &binding,
                    RefreshHoldChange::NoteFailure {
                        terminal: crate::control::terminal_refresh_rejection(&refresh_error)
                            .is_some(),
                    },
                );
                return Err(error.context(format!(
                    "refresh setup-run credentials after relay auth rejection failed: {refresh_error}"
                )));
            }
            crate::relay_auth::retry_after_setup_refresh(
                relay_binding,
                client.relay_auth_binding(device, device_secret, source),
            );
            // The retry is a new attempt: the refresh may have persisted a
            // rebound setup run. If the credential changed meanwhile, the next
            // pass captures it afresh instead.
            let retry_start = crate::control::persisted_connection_for_epoch(authority.epoch)
                .map(|connection| daemon.start_credential_observation(authority.epoch, connection));
            let Some(Ok(retry_start)) = retry_start else {
                return Err(
                    error.context("the device credential changed during the setup-run refresh")
                );
            };
            match upload_local_health_projection_with(
                client,
                device,
                device_secret,
                source,
                machine_id,
                daemon,
            ) {
                Ok(()) => {
                    settle_local_health_upload_attempt(
                        daemon,
                        &retry_start,
                        Ok(()),
                        false,
                        &binding,
                        RefreshHoldChange::ClearIfHeld,
                    );
                    Ok(())
                }
                Err(retry_error) => {
                    let hold = if local_health_upload_should_refresh_setup_run(&retry_error) {
                        RefreshHoldChange::NoteFailure { terminal: false }
                    } else {
                        RefreshHoldChange::Keep
                    };
                    settle_local_health_upload_attempt(
                        daemon,
                        &retry_start,
                        Err(local_health_upload_failure_kind(&retry_error)),
                        false,
                        &binding,
                        hold,
                    );
                    Err(retry_error)
                }
            }
        }
        Err(error) => {
            settle_local_health_upload_attempt(
                daemon,
                &start,
                Err(local_health_upload_failure_kind(&error)),
                false,
                &binding,
                RefreshHoldChange::Keep,
            );
            Err(error)
        }
    }
}

/// First wait after a local health pass whose setup-run refresh did not
/// restore authorization; it doubles per further failure up to the cap.
pub(super) const SETUP_RUN_REFRESH_HOLD_BASE: Duration = Duration::from_secs(120);

pub(super) const SETUP_RUN_REFRESH_HOLD_CAP: Duration = Duration::from_secs(30 * 60);

/// A local health pass skipped because the previous pass for the same device
/// credential and setup-run binding was rejected and the refresh did not help.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) struct LocalHealthRefreshHeld {
    /// `None` while parked until this Mac reconnects.
    pub(super) remaining: Option<Duration>,
}

impl std::fmt::Display for LocalHealthRefreshHeld {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self.remaining {
            Some(remaining) => write!(
                f,
                "local health upload held after setup-run refresh failed; next attempt in {}s",
                remaining.as_secs()
            ),
            None => write!(
                f,
                "local health upload held: Ottto ended this Mac's setup run or device credential; reconnect to resume"
            ),
        }
    }
}

/// Rejected-refresh streak for one binding. An authoritative terminal refresh
/// answer ([`crate::control::terminal_refresh_rejection`]: the run ended, or
/// the device credential is rejected) parks the binding until it changes;
/// every other rejection backs off on a capped ladder and is never final.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) struct SetupRunRefreshHold {
    pub(super) binding: [u8; 32],
    pub(super) failures: u32,
    /// `None`: parked until the binding changes.
    pub(super) until: Option<Instant>,
}

static SETUP_RUN_REFRESH_HOLD: OnceLock<Mutex<Option<SetupRunRefreshHold>>> = OnceLock::new();

pub(super) fn setup_run_refresh_hold() -> &'static Mutex<Option<SetupRunRefreshHold>> {
    SETUP_RUN_REFRESH_HOLD.get_or_init(|| Mutex::new(None))
}

/// Digest of what a reattach or credential change replaces: the device id and
/// secret, and the persisted setup run and API base. Kept in memory only.
pub(super) fn setup_run_refresh_binding(
    authority: &crate::control::CredentialAuthority,
    source: SnapshotSource,
) -> Result<[u8; 32]> {
    let mut digest = Sha256::new();
    digest.update(b"ottto:setup-run-refresh-hold:v1\0");
    digest.update(authority.device.device_id.as_bytes());
    digest.update(b"\0");
    digest.update(authority.secret.as_bytes());
    digest.update(crate::relay_auth::binding_key(
        &snapshot_api_base_url()?,
        &authority.device,
        &authority.secret,
        source.api_slug(),
    ));
    if let Some(connection) = authority.connection.as_ref() {
        digest.update(b"\0");
        digest.update(connection.setup_run_id.as_bytes());
        digest.update(b"\0");
        digest.update(connection.api_base_url.as_bytes());
    }
    Ok(digest.finalize().into())
}

pub(super) fn setup_run_refresh_hold_duration(failures: u32) -> Duration {
    SETUP_RUN_REFRESH_HOLD_BASE
        .saturating_mul(1u32 << failures.saturating_sub(1).min(5))
        .min(SETUP_RUN_REFRESH_HOLD_CAP)
}

/// The hold on `binding`, or `None` when a pass may run. A hold for a
/// different binding is dropped: the user reattached or the credential changed.
pub(super) fn setup_run_refresh_hold_at(
    hold: &mut Option<SetupRunRefreshHold>,
    binding: &[u8; 32],
    now: Instant,
) -> Option<LocalHealthRefreshHeld> {
    let current = (*hold)?;
    if &current.binding != binding {
        *hold = None;
        return None;
    }
    match current.until {
        None => Some(LocalHealthRefreshHeld { remaining: None }),
        Some(until) => until
            .checked_duration_since(now)
            .filter(|remaining| !remaining.is_zero())
            .map(|remaining| LocalHealthRefreshHeld {
                remaining: Some(remaining),
            }),
    }
}

/// Record a failed refresh for `binding`; returns the wait, or `None` when the
/// failure was terminal and the binding is parked.
pub(super) fn note_setup_run_refresh_failed_at(
    hold: &mut Option<SetupRunRefreshHold>,
    binding: &[u8; 32],
    now: Instant,
    terminal: bool,
) -> Option<Duration> {
    let failures = match *hold {
        Some(current) if &current.binding == binding => current.failures.saturating_add(1),
        _ => 1,
    };
    let wait = (!terminal).then(|| setup_run_refresh_hold_duration(failures));
    *hold = Some(SetupRunRefreshHold {
        binding: *binding,
        failures,
        until: wait.map(|wait| now + wait),
    });
    wait
}

pub(super) fn setup_run_refresh_hold_for(binding: &[u8; 32]) -> Option<LocalHealthRefreshHeld> {
    let mut hold = setup_run_refresh_hold().lock().ok()?;
    setup_run_refresh_hold_at(&mut hold, binding, Instant::now())
}

/// Record a failed refresh for `binding`, unless a hold for another binding
/// was set meanwhile: that one describes a newer setup run or credential.
pub(super) fn note_setup_run_refresh_failed(binding: &[u8; 32], terminal: bool) {
    if let Ok(mut hold) = setup_run_refresh_hold().lock() {
        if hold.is_some_and(|current| &current.binding != binding) {
            return;
        }
        match note_setup_run_refresh_failed_at(&mut hold, binding, Instant::now(), terminal) {
            Some(wait) => eprintln!(
                "local health setup-run refresh rejected; next attempt in {}s",
                wait.as_secs()
            ),
            None => eprintln!(
                "local health setup-run refresh ended by Ottto; held until this Mac reconnects"
            ),
        }
    }
}

/// Explicit recovery only: also release the local-health terminal refresh hold.
pub(crate) fn reset_relay_authorization_backoff() {
    crate::relay_auth::reset();
    clear_setup_run_refresh_hold();
}

pub(super) fn clear_setup_run_refresh_hold() {
    if let Ok(mut hold) = setup_run_refresh_hold().lock() {
        *hold = None;
    }
}

/// An accepted upload releases only the hold of the binding it used.
pub(super) fn clear_setup_run_refresh_hold_for(binding: &[u8; 32]) {
    if let Ok(mut hold) = setup_run_refresh_hold().lock() {
        if hold.is_some_and(|current| &current.binding == binding) {
            *hold = None;
        }
    }
}

pub(super) fn local_health_upload_should_refresh_setup_run(error: &anyhow::Error) -> bool {
    error
        .downcast_ref::<RelayTokenAuthorizationRejected>()
        .is_some()
        || error
            .downcast_ref::<LocalHealthAuthorizationRejected>()
            .is_some()
}

pub(super) fn local_health_upload_failure_kind(
    error: &anyhow::Error,
) -> LocalHealthUploadFailureKind {
    if error
        .downcast_ref::<LocalHealthProjectionRejected>()
        .is_some()
    {
        LocalHealthUploadFailureKind::ContractRejected
    } else if local_health_upload_should_refresh_setup_run(error) {
        LocalHealthUploadFailureKind::AuthRejected
    } else {
        LocalHealthUploadFailureKind::BackendUnreachable
    }
}

pub(super) fn local_health_upload_can_wait_quietly(error: &anyhow::Error) -> bool {
    if error
        .downcast_ref::<RelayTokenAuthorizationRejected>()
        .is_some_and(|held| held.suppressed)
    {
        return true;
    }
    if error.downcast_ref::<LocalHealthRefreshHeld>().is_some()
        || error.downcast_ref::<NoHeartbeatSource>().is_some()
    {
        return true;
    }
    let safe = safe_error(error);
    matches!(
        safe.as_str(),
        "relay device credentials are unavailable" | "machine identity is unavailable"
    ) || error
        .to_string()
        .contains("registered device has no enabled sources")
}

pub(super) fn upload_local_health_projection_with(
    client: &SnapshotApiClient,
    device: &LocalDeviceBinding,
    device_secret: &str,
    source: SnapshotSource,
    machine_id: &str,
    daemon: &LocalDaemon,
) -> Result<()> {
    let relay_token = client.issue_relay_token(device, device_secret, source)?;
    let mut status = daemon
        .status_for_trusted_client()
        .map_err(|error| anyhow!("read local health status failed: {error}"))?;
    // Pairing can select a different machine from the durable local identity.
    // Both heartbeat and health must match the paired identity on the server.
    // Set it before reprojection, using this owned status copy only.
    // Keep daemon state, machine store and setup request authority unchanged.
    // Source-control replies continue to fence on the current device binding.
    status.machine.machine_id = machine_id.to_owned();
    crate::refresh_canonical_local_health(&mut status);
    let heartbeat = status
        .runtime_heartbeat
        .as_ref()
        .ok_or_else(|| anyhow!("runtime heartbeat projection is missing"))?;
    let health = status
        .canonical_health
        .as_ref()
        .ok_or_else(|| anyhow!("canonical local health projection is missing"))?;

    let reply = client.upload_local_health_heartbeat(&relay_token, heartbeat)?;
    apply_source_control(&default_support_dir(), &reply);
    let _ = daemon.record_source_grants(device);
    client.upload_local_health_projection(&relay_token, health)?;
    Ok(())
}

pub(crate) fn agent_status_source_enabled(source: &SourceKind) -> bool {
    load_snapshot_device_credentials().is_ok_and(|(device, _)| {
        agent_status_source_enabled_in(&device, &default_support_dir(), source)
    })
}

/// Granted and not paused: the source's automatic status passes run.
pub(crate) fn agent_status_source_enabled_in(
    device: &LocalDeviceBinding,
    support_dir: &Path,
    source: &SourceKind,
) -> bool {
    enabled_snapshot_sources_in(device, support_dir)
        .into_iter()
        .any(|item| &source_kind(item) == source)
}

pub fn upload_agent_status_snapshots(snapshots: &[AgentStatusSnapshot]) -> Result<usize> {
    let (device, device_secret) = load_snapshot_device_credentials()?;
    let Some(machine_id) = snapshot_machine_id(&device)? else {
        return Err(anyhow!("machine identity is missing"));
    };
    let client = SnapshotApiClient::new(snapshot_api_base_url()?);

    let mut uploaded = 0;
    let mut failed_sources = Vec::new();
    // This standalone path runs on the shared agents too, so its transport
    // evidence feeds the same outage streak (folded per invocation): a
    // persistent agent-status-only transport failure must not stay invisible
    // to the recovery ladder just because snapshot sync was quiet.
    let mut transport_cycle = crate::net_resilience::TransportCycleOutcome::default();
    for source in enabled_snapshot_sources(&device) {
        let source_kind = source_kind(source);
        let source_snapshots = snapshots
            .iter()
            .filter(|snapshot| snapshot.source == source_kind)
            .cloned()
            .collect::<Vec<_>>();
        if source_snapshots.is_empty() {
            continue;
        }
        if source_upload_backoff_remaining(source).is_some() {
            failed_sources.push(source.api_slug());
            continue;
        }
        let relay_token = match client.issue_status_relay_token(&device, &device_secret, source) {
            Ok(token) => token,
            Err(error) => {
                transport_cycle.note_error(&error);
                failed_sources.push(source.api_slug());
                continue;
            }
        };
        match upload_agent_status(&client, &relay_token, &machine_id, &source_snapshots) {
            Ok(accepted) => {
                uploaded += accepted;
                transport_cycle.note_success();
            }
            Err(error) => {
                transport_cycle.note_error(&error);
                failed_sources.push(source.api_slug());
            }
        }
    }
    crate::net_resilience::note_sync_cycle_transport(transport_cycle);

    if !failed_sources.is_empty() {
        return Err(anyhow!(
            "agent status upload failed for {} source(s)",
            failed_sources.len()
        ));
    }

    Ok(uploaded)
}

/// Best-effort: cache the AI-generated machine icon URL the backend echoes on the
/// agent-status sync response, so the status command can surface it on
/// `status.machine.icon_url`. Never fails sync on a write error.
pub(super) fn persist_machine_icon(response: &AgentStatusSnapshotUploadResponse) {
    persist_machine_icon_at(&default_support_dir().join("machine_icon.json"), response);
}

pub(super) fn persist_machine_icon_at(path: &Path, response: &AgentStatusSnapshotUploadResponse) {
    // This is a best-effort echo, not a deletion signal: older backends omit it
    // and icon lookup failures return null. Leave the original machine binding
    // and version intact; status only applies cached icons to that machine.
    if !response
        .machine_icon_url
        .as_deref()
        .is_some_and(|url| !url.trim().is_empty())
    {
        return;
    }
    let payload = serde_json::json!({
        "machine_id": response.machine_id,
        "icon_url": response.machine_icon_url,
        "icon_version": response.machine_icon_version,
    });
    if let Ok(serialized) = serde_json::to_vec(&payload) {
        let _ = crate::locked_state_dir::replace_small_file_if_changed(
            path,
            &serialized,
            crate::locked_state_dir::SmallFileClass::PureCache,
        );
    }
}
pub(super) fn reconciliation_agent_status(
    collection: &AgentStatusCollection,
) -> &AgentStatusSnapshot {
    &collection.source_health_snapshot
}

pub(super) fn claude_evidence_session_ids(snapshots: &[SnapshotItem]) -> Vec<String> {
    snapshots
        .iter()
        .flat_map(|snapshot| {
            std::iter::once(snapshot.source_session_id.clone()).chain(
                snapshot
                    .attribution_facts
                    .iter()
                    .filter(|fact| {
                        matches!(
                            fact.field.as_str(),
                            "parent_session_ref" | "root_session_ref"
                        )
                    })
                    .map(|fact| fact.value.clone()),
            )
        })
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

pub(super) fn claude_evidence_root_session_ids(snapshots: &[SnapshotItem]) -> Vec<String> {
    snapshots
        .iter()
        .map(|snapshot| {
            snapshot
                .attribution_facts
                .iter()
                .find(|fact| fact.field == "root_session_ref")
                .map(|fact| fact.value.clone())
                .or_else(|| {
                    snapshot
                        .source_session_id
                        .split_once("_agent-")
                        .map(|(root, _)| root.to_string())
                })
                .unwrap_or_else(|| snapshot.source_session_id.clone())
        })
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

pub(super) fn trace_discard_count_is_zero(count: &u64) -> bool {
    *count == 0
}

/// Apply the exact local Claude API/trace evidence path used by production.
///
/// Kept as one shared derivation so privacy-safe offline audits cannot drift
/// from the sync loop's ownership, completeness, and quarantine semantics.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize)]
pub struct ClaudeLocalEvidenceStats {
    pub requested_session_count: usize,
    pub candidate_root_count: usize,
    pub paired_sidecar_root_count: usize,
    pub complete_sidecar_root_count: usize,
    pub api_incomplete_root_count: usize,
    pub trace_incomplete_root_count: usize,
    /// Strict trace reads dropped as grown or replaced; absent while empty.
    #[serde(skip_serializing_if = "crate::claude_local_otel::ClaudeTraceRowsDiscarded::is_empty")]
    pub trace_rows_discarded: crate::claude_local_otel::ClaudeTraceRowsDiscarded,
    /// Items whose upload this page deferred because it discarded their
    /// family's strict trace read.
    #[serde(skip_serializing_if = "trace_discard_count_is_zero")]
    pub trace_discard_deferred_items: u64,
    pub api_evidence_row_count: usize,
    pub trace_evidence_row_count: usize,
    pub exact_request_set_root_count: usize,
    pub request_set_mismatch_root_count: usize,
    pub api_only_request_count: usize,
    pub trace_only_request_count: usize,
    pub identity_complete_session_count: usize,
    pub request_index_complete_session_count: usize,
    pub explicit_owned_start_session_count: usize,
    pub session_exclusive_reported_usage_count: usize,
    pub effort_evidence_load_failed: bool,
    pub own_request_complete_root_count: usize,
    pub own_request_unknown_root_count: usize,
    /// Request-census shadow of a complete Claude terminal scan; absent
    /// otherwise.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub request_census: Option<crate::snapshots::ClaudeRequestCensusShadowCounts>,
    /// How this pass's Claude context scalars were decided (proof or file
    /// birth rule) and why any were withheld. Local only, never uploaded.
    /// Logged on its own line; kept out of this struct's serialized form so
    /// the counts line and snapshot-audit stay unchanged.
    #[serde(skip)]
    pub context_file_birth: crate::snapshots::ClaudeContextFileBirthCounts,
}

